  $('#sb-closure-action').textContent=shorteningPreview?'采用精简口播与字幕':'保留口播，采用建议时长';$('#sb-closure-alternative').textContent='AI 精简口播（付费预览）';
  if(!q.scenes.length)rows.append(node('p','口播时长无冲突。其他时长或分镜数量问题请在对应分镜中调整。'));
